sp_widget.client_script:
api.controller = function ($scope) {
  var c = this;

  c.loading = false;
  c.searchQuery = "";
  c.activeFilter = c.data.activeFilter || "all";

  c.tabs = [
    { key: "all", label: "All Visits", icon: "glyphicon-list" },
    { key: "future", label: "Future", icon: "glyphicon-forward" },
    { key: "today", label: "Today", icon: "glyphicon-calendar" },
    { key: "pending", label: "Pending", icon: "glyphicon-time" },
    { key: "checked_in", label: "Checked In", icon: "glyphicon-log-in" }
  ];

  c.setFilter = function (filterKey) {
    c.activeFilter = filterKey;
    c.loading = true;
    c.server.get({ action: "filter", filter: filterKey }).then(
      function (r) {
        c.data = r.data;
        c.loading = false;
      },
      function () {
        c.loading = false;
      }
    );
  };

  c.goToDetail = function (sysId) {
    window.location.href = "?id=x_1085196_visita_0_visit_detail&sys_id=" + sysId;
  };

  c.getStatusClass = function (status) {
    var map = {
      pending: "label-warning",
      approved: "label-info",
      checked_in: "label-success",
      checked_out: "label-default",
      cancelled: "label-danger",
      rejected: "label-danger"
    };
    return map[status] || "label-default";
  };

  c.getStatusLabel = function (status) {
    var map = {
      pending: "Pending",
      approved: "Approved",
      checked_in: "Checked In",
      checked_out: "Checked Out",
      cancelled: "Cancelled",
      rejected: "Rejected"
    };
    return map[status] || status;
  };
};

sp_widget.css:
/* Card */
.sp-card {
  display: flex;
  flex-direction: column;
  width: 100%;
  border: 1px solid $border-tertiary;
  border-radius: $border-radius-large;
  box-shadow: 0 1px 4px rgba($text-color, 0.07);
  background: $background-primary;
  overflow: hidden;
  margin-bottom: 0;
}
.sp-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 24px;
  background: $background-primary;
  border-bottom: 1px solid $border-tertiary;
  min-height: 52px;
}
.sp-card-title {
  font-size: $font-size-large;
  font-weight: 600;
  color: $text-color;
  margin: 0;
}
.sp-card-icon { margin-right: 8px; color: $brand-primary; font-size: 16px; }
.sp-card-body-flush { padding: 0; flex: 1 1 auto; overflow: hidden; }
.sp-card-body { padding: 24px; flex: 1 1 auto; }

/* Tabs */
.sp-tabs-bar {
  display: flex;
  gap: 0;
  border-bottom: 2px solid $border-tertiary;
  background: $background-secondary;
  padding: 0 16px;
  overflow-x: auto;
}
.sp-tab-btn {
  background: transparent;
  border: none;
  border-bottom: 2px solid transparent;
  padding: 12px 16px;
  font-size: $font-size-base;
  font-weight: 500;
  color: $text-muted;
  cursor: pointer;
  white-space: nowrap;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-bottom: -2px;
  transition: color 0.15s, border-color 0.15s;
  &:hover {
    color: $text-color;
  }
}
.sp-tab-active {
  color: $brand-primary;
  border-bottom-color: $brand-primary;
  font-weight: 600;
}

/* Toolbar */
.sp-table-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  border-bottom: 1px solid $border-tertiary;
  gap: 12px;
  flex-wrap: wrap;
}
.sp-search-box { position: relative; }
.sp-search-icon {
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  color: $text-muted;
  font-size: 12px;
}
.sp-search-input {
  border: 1px solid $border-tertiary;
  border-radius: $border-radius-base;
  height: 44px;
  width: 280px;
  padding: 0 10px 0 30px;
  font-size: $font-size-small;
  background: $background-primary;
  color: $text-color;
  &:focus {
    border-color: $brand-primary;
    outline: none;
  }
}

/* Table */
.sp-th {
  font-size: 12px;
  font-weight: 600;
  color: $text-muted;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  padding: 12px 16px;
  border-bottom: 2px solid $border-tertiary;
  background: $background-secondary;
}
.sp-td {
  font-size: $font-size-small;
  padding: 12px 16px;
  color: $text-color;
  border-bottom: 1px solid $border-tertiary;
  vertical-align: middle;
}
.sp-clickable-row {
  cursor: pointer;
  &:hover { background: $background-secondary; }
}

/* Loading */
.sp-loader {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 48px;
  color: $text-muted;
}
.sp-spinner {
  width: 36px;
  height: 36px;
  border: 3px solid $border-tertiary;
  border-top-color: $brand-primary;
  border-radius: 50%;
  animation: sp-spin 0.7s linear infinite;
  margin-bottom: 12px;
}
.sp-loader-text { font-size: $font-size-small; color: $text-muted; }
@keyframes sp-spin { to { transform: rotate(360deg); } }

/* Empty State */
.sp-empty-state { padding: 64px 24px; }
.sp-empty-icon {
  font-size: 48px;
  margin-bottom: 16px;
  display: block;
  opacity: 0.35;
  color: $text-muted;
}
.sp-empty-title {
  font-size: $font-size-large;
  font-weight: 600;
  color: $text-color;
  margin-bottom: 8px;
}

sp_widget.script:
(function () {
  data.visits = [];
  data.message = "";
  data.activeFilter = "all";

  try {
    // Get filter from input (tab click), URL param, or widget option default
    var filter = "";
    if (input && input.action === "filter") {
      filter = input.filter || "all";
    } else {
      filter = $sp.getParameter("filter") || (options && options.default_filter) || "all";
    }
    data.activeFilter = filter;

    var gr = new GlideRecord("x_1085196_visita_0_visit");

    if (filter === "today") {
      var today = new GlideDate();
      var todayStr = today.getByFormat("yyyy-MM-dd");
      gr.addQuery("visit_date", todayStr);
    } else if (filter === "future") {
      gr.addQuery("visit_date", ">=", new GlideDateTime().getValue());
    } else if (filter === "pending") {
      gr.addQuery("status", "pending");
    } else if (filter === "checked_in") {
      gr.addQuery("status", "checked_in");
    } else if (filter === "approved") {
      gr.addQuery("status", "approved");
    }
    // "all" = no filter

    gr.orderByDesc("visit_date");
    gr.orderByDesc("sys_created_on");
    gr.setLimit(100);
    gr.query();

    while (gr.next()) {
      data.visits.push({
        sys_id: gr.getUniqueValue(),
        number: gr.getValue("number"),
        visitor_name: gr.getValue("visitor_name"),
        visitor_email: gr.getValue("visitor_email"),
        visitor_company: gr.getValue("visitor_company"),
        host: gr.getDisplayValue("host") + "",
        status: gr.getValue("status"),
        visit_date: gr.getDisplayValue("visit_date") + "",
        purpose: gr.getValue("purpose"),
        number_of_guests: gr.getValue("number_of_guests")
      });
    }
  } catch (e) {
    gs.error("Visit List widget error: " + e.message);
    data.message = "An error occurred loading visits.";
  }
})();
